///////// 5. 일반/업무 함수 영역 /////////
/********************************************** 
 * 함수명   : scwin.select_list_call()
 * 설명     : 초기 조회 
 ***********************************************/
scwin.select_list_call = function() {

    dma_select_list.set("listStatCd", "A");
    dma_select_list.set("spotIsuTrdMktTpCd", "0");
    dma_select_list.set("searchComAbbrv", "");
    dma_select_list.set("beginIndex", "");
    dma_select_list.set("page",  1);
    dma_select_list.set("size",  10);

    $c.sbm.execute(sbm_select_list, dma_select_list.getJSON());
};

/********************************************** 
 * 함수명   : Jongmok()
 * 설명       : 가나다라..검색
 ***********************************************/
scwin.Jongmok = function(prevval, nextval) {
    let chgVal = "A";

    if ((prevval === "가") && (nextval === "나")) {
        chgVal = "A";

    } else if ((prevval === "나") && (nextval === "다")) {
        chgVal = "B";

    } else if ((prevval === "다") && (nextval === "라")) {
        chgVal = "C";

    } else if ((prevval === "라") && (nextval === "마")) {
        chgVal = "D";

    } else if ((prevval === "마") && (nextval === "바")) {                
        chgVal = "E";

    } else if ((prevval === "바") && (nextval === "사")) {                
        chgVal = "F";

    } else if ((prevval === "사") && (nextval === "아")) {                
        chgVal = "G";

    } else if ((prevval === "아") && (nextval === "자")) {               
        chgVal = "H";

    } else if ((prevval === "자") && (nextval === "카")) {    
        chgVal = "I";

    } else if ((prevval === "카") && (nextval === "타")) { 
        chgVal = "J";

    } else if ((prevval === "타") && (nextval === "파")) {       
        chgVal = "K";

    } else if ((prevval === "파") && (nextval === "하")) {
        chgVal = "L";

    } else if ((prevval === "하") && (nextval === "힝")) {         
        chgVal = "M";

    } else if ((prevval === "A") && (nextval === "Z")) {         
        chgVal = "AZ";
    } else{
        chgVal = "ETC";

    }

    dma_select_list.set("listStatCd", combo_stat.getValue());
    dma_select_list.set("spotIsuTrdMktTpCd", combo_market.getValue());
    dma_select_list.set("searchComAbbrv", txb_jongmokName.getValue());
    dma_select_list.set("beginIndex", chgVal);
    dma_select_list.set("page",  1);
    dma_select_list.set("size",  10);

    $c.sbm.execute(sbm_select_list, dma_select_list.getJSON());
}

/********************************************** 
 * 함수명   : selfClose()
 * 설명       : 창 닫기
 ***********************************************/
scwin.selfClose = async function() {

    $c.win.closePopup( );
};

scwin.JongmokSearch = function() {

    //console.log(combo_market.getValue() +"|"+ combo_stat.getValue() + " |"+ txb_jongmokName.getValue() );
    dma_select_list.set("listStatCd", combo_stat.getValue());
    dma_select_list.set("spotIsuTrdMktTpCd", combo_market.getValue());
    dma_select_list.set("searchComAbbrv", txb_jongmokName.getValue());
    dma_select_list.set("beginIndex", "");
    dma_select_list.set("page",  1);
    dma_select_list.set("size",  10);

    $c.sbm.execute(sbm_select_list, dma_select_list.getJSON());
}
